// ─── BeerFull SVG ─────────────────────────────────────────────────────────────
// Shows the filled mug. fillProgress (0→1) animates liquid rising bottom→top.
// At fillProgress=0 → nothing visible (fully clipped).
// At fillProgress=1 → entire mug filled.
// The empty outline ghost is only shown while the fill is actively animating
// (0 < fillProgress < 1) so there's a container to watch liquid rise into.

const BeerFull: React.FC<{
  scale?: number;
  fillProgress?: number;
  uid: string;
}> = ({ scale = 1, fillProgress = 1, uid }) => {
  // Clip rect rises from bottom: at fp=0 clip covers nothing, at fp=1 covers all 254px
  const clipY = interpolate(fillProgress, [0, 1], [254, 0]);
  const clipH = 254 - clipY;

  // Ghost outline: visible only while actively filling so user can see
  // the shape before liquid reaches the top. Fades out as fill completes.
  const ghostOpacity =
    fillProgress > 0 && fillProgress < 1
      ? interpolate(fillProgress, [0, 0.15, 0.85, 1], [0, 0.35, 0.35, 0])
      : fillProgress >= 1
      ? 0
      : 0;

  return (
    <svg
      width={200 * scale}
      height={254 * scale}
      viewBox="0 0 200 254"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      style={{ imageRendering: "pixelated", display: "block" }}
    >
      <defs>
        <linearGradient
          id={`fg-${uid}`}
          x1="100"
          y1="0"
          x2="100"
          y2="253.347"
          gradientUnits="userSpaceOnUse"
        >
          <stop stopColor="#F8BEDB" />
          <stop offset="1" stopColor="#1E61F0" />
        </linearGradient>

        {/* Rising-liquid clip: a rect that grows upward as fillProgress increases */}
        <clipPath id={`frc-${uid}`}>
          <rect x="0" y={clipY} width="200" height={clipH} />
        </clipPath>

        {/* Outline mask — used by the ghost-outline path only */}
        <mask id={`fom-${uid}`} fill="white">
          <path d="M133.333 6.66504H140.002V13.3301H153.336V19.9951H160.001V33.3262H166.666V39.9912H173.339V53.3242H166.666V60.0186H160.001V73.3496H159.999V239.983H153.335V246.678H146.67V253.344H33.3369V246.678H26.668V239.983H19.999V73.3496H13.334V60.0186H6.66895V52.1572H0V40.9805H6.66895V33.3262H26.668V19.9951H39.9951V13.3301H73.3359V6.66504H86.666V0H133.333V6.66504ZM193.339 113.338H200V160.004H193.339V173.327H160.005V159.994H186.667V113.341H160.005V100.007H193.339V113.338Z" />
        </mask>
      </defs>

      {/* Ghost outline — only visible during active fill so the mug shape is apparent */}
      {ghostOpacity > 0 && (
        <path
          d="M133.333 6.66504H140.002V13.3301H153.336V19.9951H160.001V33.3262H166.666V39.9912H173.339V53.3242H166.666V60.0186H160.001V73.3496H159.999V239.983H153.335V246.678H146.67V253.344H33.3369V246.678H26.668V239.983H19.999V73.3496H13.334V60.0186H6.66895V52.1572H0V40.9805H6.66895V33.3262H26.668V19.9951H39.9951V13.3301H73.3359V6.66504H86.666V0H133.333V6.66504ZM193.339 113.338H200V160.004H193.339V173.327H160.005V159.994H186.667V113.341H160.005V100.007H193.339V113.338Z"
          fill={`url(#fg-${uid})`}
          mask={`url(#fom-${uid})`}
          opacity={ghostOpacity}
        />
      )}

      {/* Solid filled body — clipped to rise from bottom */}
      <g clipPath={`url(#frc-${uid})`}>
        <path
          d="M159.999 73.3467H160.001V240.016H153.333V246.682H146.668V253.347H33.333V246.682H26.6641V240.016H19.999V73.3496H13.3301V60.0166H159.999V73.3467ZM193.339 113.338H200V160.006H193.339V173.328H160.005V159.995H186.666V113.341H160.005V100.008H193.339V113.338ZM133.33 6.66602H140.003V13.3311H153.337V19.9961H160V33.3262H166.663V39.9922H173.34V53.3252H166.663V59.9902H6.66895V53.3252H0V39.9922H6.66895V33.3262H26.6641V19.9961H39.9951V13.3311H73.3359V6.66602H86.6621V0H133.33V6.66602Z"
          fill={`url(#fg-${uid})`}
        />
      </g>
    </svg>
  );
};

// ─── Particle Burst ────────────────────────────────────────────────────────────

const PARTICLE_DEFS = [
  { angle: -80, dist: 60, color: "#F8BEDB" },
  { angle: -45, dist: 80, color: "#FF64B8" },
  { angle: -110, dist: 70, color: "#1E61F0" },
  { angle: -60, dist: 90, color: "#F8BEDB" },
  { angle: -95, dist: 55, color: "#7B9EFF" },
  { angle: -130, dist: 75, color: "#FF64B8" },
];

const ParticleBurst: React.FC<{
  elapsed: number; // frames since trigger
}> = ({ elapsed }) => {
  if (elapsed < 0 || elapsed > 20) return null;
  const t = elapsed / 20;
  return (
    <div
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        pointerEvents: "none",
      }}
    >
      {PARTICLE_DEFS.map((p, i) => {
        const rad = (p.angle * Math.PI) / 180;
        const x = Math.cos(rad) * p.dist * t;
        const y = Math.sin(rad) * p.dist * t;
        const opacity = interpolate(t, [0, 0.3, 1], [0, 1, 0]);
        const size = interpolate(t, [0, 0.3, 1], [4, 10, 4]);
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: `calc(50% + ${x}px)`,
              top: `calc(50% + ${y}px)`,
              width: size,
              height: size,
              borderRadius: 0,
              backgroundColor: p.color,
              opacity,
              transform: "translate(-50%, -50%)",
              imageRendering: "pixelated",
            }}
          />
        );
      })}
    </div>
  );
};

// ─── Plus One Pop ─────────────────────────────────────────────────────────────

const PlusOnePop: React.FC<{ elapsed: number }> = ({ elapsed }) => {
  if (elapsed < 0 || elapsed > 22) return null;
  const t = elapsed / 22;
  const y = interpolate(t, [0, 1], [0, -80]);
  const opacity = interpolate(t, [0, 0.2, 0.7, 1], [0, 1, 1, 0]);
  const scaleVal = interpolate(t, [0, 0.3, 1], [0.5, 1.2, 1]);
  return (
    <div
      style={{
        position: "absolute",
        top: "50%",
        left: "50%",
        transform: `translate(-50%, calc(-50% + ${y}px)) scale(${scaleVal})`,
        opacity,
        fontFamily: "'Inter', sans-serif",
        fontSize: 32,
        fontWeight: 900,
        color: "#F8BEDB",
        letterSpacing: "0.05em",
        textShadow: "0 0 10px #F8BEDB, 0 0 20px #FF64B8",
        whiteSpace: "nowrap",
        pointerEvents: "none",
      }}
    >
      +1
    </div>
  );
};

// ─── Timing ────────────────────────────────────────────────────────────────────

// Bounce-in stagger delays (frames from scene start)
const INTRO_DELAYS = [0, 5, 9, 13, 17];

// Phase 2 fill windows for mugs 1–4 (mug 0 is always full).
// start/end: frames over which fillProgress goes 0→1
// plusOne: frame at which the +1 / particle burst fires
const FILL_PHASES: Array<{
  start: number;
  end: number;
  plusOne: number;
} | null> = [
  null,                                    // mug 0: always full, no fill animation
  { start: 33, end: 41, plusOne: 42 },     // mug 1 (index 1)
  { start: 43, end: 51, plusOne: 52 },     // mug 2 (index 2)
  { start: 53, end: 61, plusOne: 62 },     // mug 3 (index 3)
  { start: 63, end: 71, plusOne: 72 },     // mug 4 (index 4)
];

const MUG_SCALE = 0.52;
const ALL_FULL_FRAME = 75; // frame after which idle glow starts

// ─── Single Mug ───────────────────────────────────────────────────────────────

const Mug: React.FC<{ mugIndex: number }> = ({ mugIndex }) => {
  const frame = useCurrentFrame();
  const { fps: videoFps } = useVideoConfig();
  const uid = `mug${mugIndex}`;

  // ── Bounce-in spring (uses frame directly; delay is a frame offset) ──
  const bounceProgress = spring({
    frame,
    fps: videoFps,
    delay: INTRO_DELAYS[mugIndex],
    config: { damping: 80, stiffness: 400, mass: 0.8 },
  });
  const entryScale = interpolate(bounceProgress, [0, 1], [0, 1]);

  // ── Fill progress for mugs 1–4 ──
  // mugIndex 0 → always 1 (full)
  // mugIndex 1–4 → 0 until fill window, then 0→1, then stays at 1
  const phase = FILL_PHASES[mugIndex];

  const fillProgress: number =
    mugIndex === 0
      ? 1
      : phase
      ? interpolate(frame, [phase.start, phase.end], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })
      : 0;

  // ── Completion pulse: a quick scale bump the moment fill reaches 1 ──
  // Implemented via frame-based interpolation (not spring delay) to avoid
  // the spring-delay-as-absolute-frame bug in the previous version.
  let completionScale = 1;
  if (mugIndex !== 0 && phase) {
    const punchWindow = 8; // frames for bump
    const punchT = interpolate(
      frame,
      [phase.end, phase.end + punchWindow * 0.4, phase.end + punchWindow],
      [1, 1.2, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );
    completionScale = punchT;
  }

  const finalScale = entryScale * completionScale;

  // ── Entry shimmer: white flash for ~6 frames after bounce-in delay ──
  const shimmerStart = INTRO_DELAYS[mugIndex];
  const shimmerOpacity =
    frame >= shimmerStart && frame <= shimmerStart + 6
      ? interpolate(
          frame,
          [shimmerStart, shimmerStart + 3, shimmerStart + 6],
          [0, 0.85, 0]
        )
      : 0;

  // ── Idle glow after all mugs are filled ──
  const glowOpacity =
    frame > ALL_FULL_FRAME
      ? Math.abs(
          Math.sin((frame - ALL_FULL_FRAME) * 0.08 + mugIndex * 0.8)
        ) * 0.5
      : 0;

  // ── Particle / +1 effects ──
  const plusOneFrame = phase ? phase.plusOne : -1;
  const effectElapsed = plusOneFrame >= 0 ? frame - plusOneFrame : -1;
  const showEffects = mugIndex !== 0 && phase !== null && effectElapsed >= 0;

  // ── Render decision ──
  // mug 0     → BeerFull (always, fillProgress=1)
  // mugs 1–4  → BeerEmpty when fillProgress is exactly 0
  //           → BeerFull with rising clip once fillProgress > 0
  //
  // Using a small epsilon (0.005) to absorb any floating-point rounding
  // so the empty→full switch doesn't flicker on the boundary frame.
  const isFilling = fillProgress > 0.005;

  return (
    <div
      style={{
        position: "relative",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        width: 200 * MUG_SCALE,
        height: 254 * MUG_SCALE,
        transform: `scale(${finalScale})`,
        transformOrigin: "center bottom",
      }}
    >
      {/* Idle glow halo */}
      <div
        style={{
          position: "absolute",
          inset: -24,
          borderRadius: 8,
          background: `radial-gradient(ellipse at center, rgba(248,190,219,${glowOpacity}) 0%, transparent 70%)`,
          pointerEvents: "none",
        }}
      />

      {/* Entry shimmer flash */}
      {shimmerOpacity > 0 && (
        <div
          style={{
            position: "absolute",
            inset: -4,
            backgroundColor: `rgba(255,255,255,${shimmerOpacity})`,
            borderRadius: 4,
            pointerEvents: "none",
            zIndex: 10,
          }}
        />
      )}

      {/* ── Mug body ── */}
      {mugIndex === 0 ? (
        // Mug 0: unconditionally full, no animation needed
        <BeerFull scale={MUG_SCALE} fillProgress={1} uid={uid} />
      ) : isFilling ? (
        // Fill animation in progress (or complete) — BeerFull with rising clip
        <BeerFull scale={MUG_SCALE} fillProgress={fillProgress} uid={uid} />
      ) : (
        // Before fill window — show hollow empty outline
        <BeerEmpty scale={MUG_SCALE} uid={uid} />
      )}

      {/* Particles and +1 pop */}
      {showEffects && (
        <>
          <ParticleBurst elapsed={effectElapsed} />
          <PlusOnePop elapsed={effectElapsed} />
        </>
      )}
    </div>
  );
};

// ─── HUD Scene ────────────────────────────────────────────────────────────────

const BeerHUDScene: React.FC = () => (
  <AbsoluteFill
    style={{
      fontFamily: "'Inter', sans-serif",
      backgroundColor: "transparent",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
    }}
  >
    <div
      style={{
        display: "flex",
        flexDirection: "row",
        alignItems: "flex-end",
        justifyContent: "center",
        gap: 28,
      }}
    >
      {Array.from({ length: 5 }, (_, i) => (
        <Mug key={i} mugIndex={i} />
      ))}
    </div>
  </AbsoluteFill>
);

// ─── Composition ──────────────────────────────────────────────────────────────

const MainComposition: React.FC = () => (
  <TransitionSeries>
    <TransitionSeries.Sequence durationInFrames={SCENE_DURATION}>
      <BeerHUDScene />
    </TransitionSeries.Sequence>
  </TransitionSeries>
);

export default MainComposition;
